"use client";

import * as React from "react";
import { Tabs as TabsPrimitive } from "@base-ui/react/tabs";

import { cn } from "@/lib/utils";
import { focusRing, wellInset } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Paddock Tabs root: owns which panel shows. */
const Tabs = TabsPrimitive.Root;

/**
 * Paddock TabsList: a view switch on a recessed light-grey track with small
 * rounded corners.
 */
const TabsList = React.forwardRef<
  HTMLDivElement,
  WithClassName<TabsPrimitive.List.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.List
    ref={ref}
    data-slot="tabs-list"
    className={cn(
      "inline-flex h-10 items-center justify-center gap-0.5 rounded-md p-1 text-muted-foreground",
      wellInset,
      className,
    )}
    {...props}
  />
));
TabsList.displayName = "TabsList";

/**
 * Paddock TabsTrigger: a muted label in a small rounded segment. The active
 * tab is a raised white segment with a 1px cool border and a faint drop.
 */
const TabsTrigger = React.forwardRef<
  HTMLButtonElement,
  WithClassName<TabsPrimitive.Tab.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Tab
    ref={ref}
    data-slot="tabs-trigger"
    className={cn(
      "inline-flex h-full items-center justify-center gap-1.5 whitespace-nowrap rounded-sm px-3.5 text-sm",
      "text-muted-foreground transition-[color,box-shadow,background-color] duration-base ease-out",
      "hover:text-foreground",
      focusRing,
      "data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
      "data-[active]:bg-card data-[active]:font-medium data-[active]:text-foreground data-[active]:shadow-(--segment-lift)",
      "[&_svg]:size-4 [&_svg]:shrink-0",
      className,
    )}
    {...props}
  />
));
TabsTrigger.displayName = "TabsTrigger";

/** Paddock TabsContent: the active panel, set below the tab row. */
const TabsContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<TabsPrimitive.Panel.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Panel
    ref={ref}
    data-slot="tabs-content"
    className={cn("mt-4 rounded-lg", focusRing, className)}
    {...props}
  />
));
TabsContent.displayName = "TabsContent";

export { Tabs, TabsList, TabsTrigger, TabsContent };
